                memcpy(&value, point, 4);
                if (value != inv)
                {
                    values.assign(byteData, byteData + size);
                    return FIT_TRUE;
                }
                point += 4;
                bytes -= 4;
            }
        }
        break;

        case 8:
        {
            FIT_UINT64 inv;
            memcpy(&inv, invalid, 8);
            while (bytes > 0)
            {
                FIT_UINT64 value;
                memcpy(&value, point, 8);
                if (value != inv)
                {
                    values.assign(byteData, byteData + size);
                    return FIT_TRUE;
                }
                point += 8;
                bytes -= 8;
            }
        }
        break;

        default:
        {
            while (bytes > 0)
